const { MAX_QUEUE_SIZE } = require('./config');

class Queue {
  constructor() {
    this.items = [];
  }

  enqueue(item) {
    if (this.items.length >= MAX_QUEUE_SIZE) {
      throw new Error('Queue overflow');
    }
    this.items.push(item);
  }

  dequeue() {
    if (this.items.length === 0) {
      throw new Error('Queue underflow');
    }
    return this.items.shift();
  }

  peek() {
    if (this.items.length === 0) {
      throw new Error('Queue underflow');
    }
    return this.items[0];
  }

  get size() {
    return this.items.length;
  }

  isEmpty() {
    return this.items.length === 0;
  }

  clear() {
    this.items = [];
  }

  toArray() {
    return [...this.items];
  }

  static fromArray(arr) {
    const q = new Queue();
    for (const item of arr) {
      q.enqueue(item);
    }
    return q;
  }

  map(fn) {
    const q = new Queue();
    for (const item of this.items) {
      q.enqueue(fn(item));
    }
    return q;
  }

  filter(fn) {
    const q = new Queue();
    for (const item of this.items) {
      if (fn(item)) {
        q.enqueue(item);
      }
    }
    return q;
  }

  reduce(fn, initial) {
    let acc = initial;
    for (const item of this.items) {
      acc = fn(acc, item);
    }
    return acc;
  }

  forEach(fn) {
    for (const item of this.items) {
      fn(item);
    }
  }

  contains(item) {
    return this.items.includes(item);
  }

  reverse() {
    const q = new Queue();
    for (let i = this.items.length - 1; i >= 0; i--) {
      q.enqueue(this.items[i]);
    }
    return q;
  }

  clone() {
    const q = new Queue();
    for (const item of this.items) {
      q.enqueue(item);
    }
    return q;
  }

  equals(other) {
    if (!(other instanceof Queue)) return false;
    if (this.size !== other.size) return false;
    for (let i = 0; i < this.items.length; i++) {
      if (this.items[i] !== other.items[i]) return false;
    }
    return true;
  }

  toString() {
    return `Queue(${this.items.join(', ')})`;
  }

  [Symbol.iterator]() {
    return this.items[Symbol.iterator]();
  }

