#include "queue.h"
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Queue {
    struct Node *head;
    struct Node *tail;
};

Queue *queue_create(void) {
    Queue *q = malloc(sizeof(Queue));
    if (!q) return NULL;
    q->head = q->tail = NULL;
    return q;
}

void queue_destroy(Queue *q) {
    while (q && q->head) {
        struct Node *n = q->head;
        q->head = n->next;
        free(n);
    }
    free(q);
}

int queue_is_empty(const Queue *q) {
    return !q || !q->head;
}

