func Convert(value float64, from, to string) (float64, error) {
	fromFactor, ok := factors[from]
	if !ok {
		return 0, fmt.Errorf("unknown unit %q", from)
	}
	toFactor, ok := factors[to]
	if !ok {
		return 0, fmt.Errorf("unknown unit %q", to)
	}
	return value * fromFactor / toFactor, nil
}

// ConvertToBase converts a value expressed in the given unit into the
// repository's canonical base unit.
func ConvertToBase(value float64, from string) (float64, error) {
	factor, ok := factors[from]
	if !ok {
		return 0, fmt.Errorf("unknown unit %q", from)
	}
	return value * factor, nil
}

