int rb_push(ring_buffer_t *rb, int value) {
    if (rb->count == rb->capacity) {
        return -1;
    }
    rb->storage[rb->tail] = value;
    rb->tail = (rb->tail + 1) % rb->capacity;
    rb->count++;
    return 0;
}

int rb_pop(ring_buffer_t *rb, int *out) {
    if (rb->count == 0) {
        return -1;
    }
    *out = rb->storage[rb->head];
    rb->head = (rb->head + 1) % rb->capacity;
    rb->count--;
    return 0;
}

